using Aict.Core;
using Aict.Beta;
using Microsoft.VisualStudio.TestTools.UnitTesting;
namespace Aict.Core.Tests;
[TestClass] public class WebsitePatternTests {
    [TestMethod] public void PageRulesKeepPathIgnoreQueryAndNeverAllowEntireSite(){var p=WebsitePattern.Normalize("https://bilibili.com/video/BV1ABC/?spm_id_from=test");Assert.AreEqual("bilibili.com/video/BV1ABC",p);Assert.IsTrue(WebsitePattern.Matches(p,"https://bilibili.com/video/bv1abc?p=2"));Assert.IsFalse(WebsitePattern.Matches(p,"https://bilibili.com/video/BV1OTHER"));Assert.IsFalse(WebsitePattern.Matches(p,"https://evil.bilibili.com/video/BV1ABC"));Assert.AreEqual(p,WebsitePattern.Normalize(p));}
    [TestMethod] public void KeywordGlobsMatchPagePathsAndDomains(){foreach(string p in new[]{"*bilibili*","*favlist*","*BV1ABC*","https://*.bilibili.com/video/*"})Assert.IsTrue(WebsitePattern.Matches(p,"https://www.bilibili.com/video/BV1ABC?favlist=1"));Assert.IsFalse(WebsitePattern.Matches("*youtube*","https://example.com/"));Assert.IsFalse(WebsitePattern.Matches("file://*.*","https://example.com/"));Assert.IsTrue(WebsitePattern.Matches("bücher.example","https://xn--bcher-kva.example/"));}
    [TestMethod] public void DomainBoundariesAndInputValidationStayStrict(){Assert.IsTrue(WebsitePattern.Matches("example.com","https://www.example.com/"));Assert.IsFalse(WebsitePattern.Matches("example.com","https://notexample.com/"));foreach(string p in new[]{"javascript:alert(1)","https://user:secret@example.com/a","bad value","ftp://example.com/a",new string('a',2049)})Assert.ThrowsExactly<ArgumentException>(()=>WebsitePattern.Normalize(p));}
    [TestMethod] public void PageExceptionsAreGroupLocalAndQuotaUsesActualPage(){var g=new RuleGroup{Id=Guid.NewGuid(),Name="页面",WebsiteMode=TargetMode.BlockSelected,WebsiteDomains=["*bilibili*"],WebsiteExceptions=["*favlist*","bilibili.com/video/BV1ABC"],AlwaysBlock=true};var plan=new WebGroup(g.Id,g.WebsiteMode,g.WebsiteDomains,g.WebsiteExceptions,[]);Assert.IsFalse(Plans.Denies(plan,"https://bilibili.com/video/BV1ABC?tracking=1"));Assert.IsTrue(Plans.Denies(plan,"https://bilibili.com/video/BV1XYZ"));Assert.IsFalse(RuleEngine.Matches(g,new(null,"bilibili.com"){WebsiteUrl="https://bilibili.com/video/BV1ABC"}));Assert.IsTrue(RuleEngine.Matches(g,new(null,"bilibili.com"){WebsiteUrl="https://bilibili.com/video/BV1XYZ"}));}
    [TestMethod] public void RelaxingPageExceptionsWaitsButAddingBlockedPatternsTightens(){var g=new RuleGroup{Id=Guid.NewGuid(),Name="页面",WebsiteMode=TargetMode.BlockSelected,WebsiteDomains=["*bilibili*"],AlwaysBlock=true};var p=new PolicyConfiguration{Groups=[g]};var now=DateTimeOffset.UtcNow;Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(p,p with{Groups=[g with{WebsiteDomains=["*bilibili*","*youtube*"]}]},now));Assert.IsFalse(PolicyStrength.IsAtLeastAsRestrictive(p,p with{Groups=[g with{WebsiteExceptions=["*favlist*"]}]},now));Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(p,p,now));}
    [TestMethod] public void UrlProtocolRejectsSpoofedHostAndNonHttp(){var b=new BrowserSample("Edge",new string('1',32),"",true,false,"example.com"){Url="https://example.com/a",PatternVersion=1};new Request{Command=Command.BrowserPulse,Browser=b}.Validate();Assert.ThrowsExactly<ArgumentException>(()=>new Request{Command=Command.BrowserPulse,Browser=b with{Url="https://different.com/a"}}.Validate());}
}
